function confusingNumber(n) {
  const rotated = new Map([[0, 0], [1, 1], [6, 9], [8, 8], [9, 6]]);
  let rest = n;
  let flipped = 0;

  while (rest > 0) {
    const digit = rest % 10;
    if (!rotated.has(digit)) {
      return false;
    }
    flipped = flipped * 10 + rotated.get(digit);
    rest = Math.floor(rest / 10);
  }
  return flipped !== n;
}

