function confusingNumber(n) {
  const upsideDown = new Map([['0', '0'], ['1', '1'], ['6', '9'], ['8', '8'], ['9', '6']]);
  const text = String(n);
  let result = '';
  for (let i = text.length - 1; i >= 0; i--) {
    if (!upsideDown.has(text[i])) return false;
    result += upsideDown.get(text[i]);
  }
  return parseInt(result, 10) !== n;
}

