function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const good = '01689';
  const length = size === 'large' ? int(8, 9) : int(1, 6);
  const roll = rand();
  if (size === 'large' && roll < 0.1) return [1000000000];
  let text = '';
  if (roll < 0.3) {
    // A number that rotates onto itself, built from its outer pairs inwards.
    const pairs = [['0', '0'], ['1', '1'], ['6', '9'], ['8', '8'], ['9', '6']];
    const middle = ['0', '1', '8'];
    let left = '', right = '';
    for (let i = 0; i < Math.floor(length / 2); i++) {
      const [a, b] = pairs[int(i === 0 ? 1 : 0, 4)];
      left += a;
      right = b + right;
    }
    text = left + (length % 2 ? middle[int(left ? 0 : 1, 2)] : '') + right;
  } else {
    const strict = roll < 0.75;
    for (let i = 0; i < length; i++) {
      const digits = strict ? good : '0123456789';
      let d = digits[int(0, digits.length - 1)];
      if (i === 0 && d === '0') d = '1';
      text += d;
    }
  }
  return [rand() < 0.05 ? 0 : Number(text)];
}
